def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    comps=[]; labels={}
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in labels: continue
            idx=len(comps); q=deque([(r,c)]); labels[(r,c)]=idx; comp=[]
            while q:
                rr,cc=q.popleft(); comp.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0<=nr<h and 0<=nc<w and grid[nr][nc]==2 and (nr,nc) not in labels:
                        labels[(nr,nc)]=idx; q.append((nr,nc))
            comps.append(comp)
    lines=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]==1:
                if r in (0,h-1): lines.add(('c',c))
                if c in (0,w-1): lines.add(('r',r))
    selected=set()
    for axis,k in lines:
        length=w if axis=='r' else h; mid=(length-1)/2
        beam=[]; sides=[set(),set()]
        for pos in range(length):
            cell=(k,pos) if axis=='r' else (pos,k); beam.append(cell)
            idx=labels.get(cell)
            if idx is not None:
                if pos<=mid: sides[0].add(idx)
                if pos>=mid: sides[1].add(idx)
        for side in sides:
            if side:
                best=max(len(comps[i]) for i in side)
                selected.update(i for i in side if len(comps[i])==best)
        for r,c in beam: out[r][c]=1
    for i in selected:
        for r,c in comps[i]: out[r][c]=1
    return out
